"""Greedy paragraph-preserving text wrapping."""


def wrap(text, width):
    if isinstance(width, bool) or not isinstance(width, int):
        raise ValueError(f"width must be an int: {width!r}")
    if width < 1:
        raise ValueError(f"width must be at least 1: {width}")
    paragraphs, current = [], []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        elif current:
            paragraphs.append(current)
            current = []
    if current:
        paragraphs.append(current)
    out = []
    for lines in paragraphs:
        row = ""
        for word in " ".join(lines).split():
            if not row:
                row = word
            elif len(row) + 1 + len(word) <= width:
                row += " " + word
            else:
                out.append(row)
                row = word
        out.append(row)
        out.append("")
    return "\n".join(out[:-1])
